package org.apache.commons.math.optimization;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.random.JDKRandomGenerator;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.LocalizedFormats;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class MultiStartUnivariateRealOptimizer_getResult_TriageGen4Test {

    private UnivariateRealOptimizer mockOptimizer;
    private RandomGenerator mockGenerator;
    private MultiStartUnivariateRealOptimizer optimizer;

    @Before
    public void setUp() {
        mockOptimizer = mock(UnivariateRealOptimizer.class);
        mockGenerator = new JDKRandomGenerator();
        optimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 1, mockGenerator);
    }

    /**
     * Tests that getResult() correctly returns the value provided by the underlying optimizer.
     * This covers the primary execution path of the method.
     */
    @Test
    public void testGetResultReturnsValueFromOptimizer() throws ConvergenceException, FunctionEvaluationException {
        double expectedValue = 42.0;
        when(mockOptimizer.getResult()).thenReturn(expectedValue);

        double actualValue = optimizer.getResult();

        assertEquals("getResult should return the value from the underlying optimizer", expectedValue, actualValue, 1e-15);
    }

    /**
     * Tests that getResult() returns a specific value when the optimizer returns zero.
     */
    @Test
    public void testGetResultReturnsZero() {
        double expectedValue = 0.0;
        when(mockOptimizer.getResult()).thenReturn(expectedValue);

        double actualValue = optimizer.getResult();

        assertEquals("getResult should return 0.0 if the underlying optimizer returns 0.0", expectedValue, actualValue, 1e-15);
    }

    /**
     * Tests that getResult() returns a negative value when the optimizer returns a negative value.
     */
    @Test
    public void testGetResultReturnsNegativeValue() {
        double expectedValue = -123.456;
        when(mockOptimizer.getResult()).thenReturn(expectedValue);

        double actualValue = optimizer.getResult();

        assertEquals("getResult should return negative values if the underlying optimizer returns negative values", expectedValue, actualValue, 1e-15);
    }

    /**
     * Tests the behavior of getResult() when the underlying optimizer throws a RuntimeException.
     * This ensures that the exception propagates correctly.
     */
    @Test(expected = RuntimeException.class)
    public void testGetResultPropagatesRuntimeException() {
        when(mockOptimizer.getResult()).thenThrow(new RuntimeException("Optimizer error"));

        optimizer.getResult();
    }
}
